export interface ReservoirData {
  name: string;
  nameKn: string;
  location: string;
  river: string;
  state: string;
  currentLevelFeet: number;
  maxLevelFeet: number;
  inflowCusecs: number;
  outflowCusecs: number;
  percentageFull: number;
  status: 'normal' | 'high' | 'alert';
}

export interface SeasonalRainfallSummary {
  seasonName: string;
  seasonNameKn: string;
  period: string;
  actualMm: number;
  normalMm: number;
  departurePercent: number;
  status: 'normal' | 'excess' | 'deficit';
  statusLabel: string;
  statusLabelKn: string;
  nationalZones: {
    zone: string;
    zoneKn: string;
    actualMm: number;
    normalMm: number;
    status: string;
  }[];
}

